const $=(s,r=document)=>r.querySelector(s),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,data){const r=await fetch(url,{credentials:'same-origin',method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||'Please try again.');return result;}
function toast(text){$('.shop-toast')?.remove();const p=document.createElement('div');p.className='shop-toast';p.setAttribute('role','status');p.textContent=text;document.body.append(p);setTimeout(()=>p.remove(),6500);}
let catalog=[];const catalogReady=api('/api/products').then(r=>catalog=r.products).catch(e=>{toast(e.message);return [];});
async function addProduct(id,quantity=1){await catalogReady;let p=catalog.flatMap(p=>[p,...(p.variants||[])]).find(p=>p.id===id||String(p.sourceId)===String(id));if(!p)throw Error('Product not available');if(p.variable){const selected=$('#shop-variant')?.value;const values=Object.fromEntries([...document.querySelectorAll('form.variations_form select[name^=attribute_]')].map(s=>[s.name,s.value]));p=p.variants?.find(v=>selected?v.id===selected:Object.entries(v.attributes).every(([k,value])=>!value||values[k]===value));if(!p)throw Error('Choose a product size first.');}await api('/api/cart',{action:'add',id:p.id,quantity});toast('Added to your cart.');}
document.addEventListener('click',async e=>{const a=e.target.closest('[data-clone-add],.add_to_cart_button,.single_add_to_cart_button');if(!a)return;e.preventDefault();e.stopImmediatePropagation();try{const id=a.dataset.cloneAdd||a.dataset.product_id||location.pathname.split('/').filter(Boolean).pop(),qty=Number($('input.qty')?.value||1);await addProduct(id,qty);}catch(err){toast(err.message);}},true);
document.addEventListener('click',async e=>{const btn=e.target.closest('.nlx-btn');if(!btn)return;e.preventDefault();e.stopImmediatePropagation();const form=btn.closest('.nlx-form'),email=$('input[type=email]',form).value;if($('.nlx-hp input',form)?.value)return;btn.disabled=true;try{const r=await api('/api/submissions',{kind:'newsletter',email,message:''});$('.nlx-msg',form).textContent=r.message;}catch(e){$('.nlx-msg',form).textContent=e.message;}finally{btn.disabled=false;}},true);
document.addEventListener('DOMContentLoaded',()=>{
document.querySelectorAll('.phbio-aab').forEach(x=>x.classList.add('is-ready'));
catalogReady.then(()=>{document.querySelectorAll('.phbio-card').forEach(card=>{const href=$('h3 a',card)?.getAttribute('href'),p=catalog.find(p=>p.path===href);if(!p)return;const price=$('.price',card);if(price&&!p.variable)price.textContent=money(p.price);if(p.stock===0){const add=$('[data-clone-add],.add_to_cart_button',card);if(add){add.textContent='Out of stock';add.removeAttribute('data-clone-add');add.classList.remove('add_to_cart_button');add.onclick=e=>e.preventDefault();}}});});
catalogReady.then(()=>{const p=catalog.find(p=>p.path===location.pathname),summary=$('.summary.entry-summary')||$('.elementor-widget-woocommerce-product-add-to-cart');if(!p||!summary)return;const panel=document.createElement('section');panel.className='shop-page';panel.style.margin='20px 0';panel.style.padding='16px';panel.innerHTML=`${p.variable?`<label>Product size<select id="shop-variant"><option value="">Choose a size</option>${(p.variants||[]).map(v=>`<option value="${esc(v.id)}" ${!v.active||v.stock===0?'disabled':''}>${esc(v.label)} · ${money(v.price)}${!v.active||v.stock===0?' · unavailable':''}</option>`).join('')}</select></label>`:`<p>${money(p.price)}</p>`}<label>Quantity<input id="shop-quantity" type="number" min="1" max="99" value="1"></label><button id="shop-add">Add to cart</button>`;summary.append(panel);$('#shop-add').onclick=async()=>{try{await addProduct(p.id,Number($('#shop-quantity').value));}catch(e){toast(e.message);}};});
document.querySelectorAll('.phbio-catalog').forEach(root=>{const cards=[...root.querySelectorAll('.phbio-card')],filters=$('.phbio-filters',root),sentinel=$('.phbio-sentinel',root);let selected=cards,shown=20;function render(){cards.forEach(c=>{const visible=selected.includes(c)&&selected.indexOf(c)<shown;c.classList.toggle('phbio-deferred',!visible);c.classList.toggle('phbio-revealed',visible);});sentinel?.classList.toggle('hidden',shown>=selected.length);}filters?.addEventListener('click',e=>{const b=e.target.closest('.phbio-pill');if(!b)return;e.stopImmediatePropagation();filters.querySelectorAll('.phbio-pill').forEach(x=>x.classList.toggle('active',x===b));selected=b.dataset.cat==='all'?cards:cards.filter(c=>[...c.querySelectorAll('[data-cat]')].some(t=>t.dataset.cat===b.dataset.cat));shown=20;render();},true);if(sentinel)new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){shown+=20;render();}},{rootMargin:'400px'}).observe(sentinel);render();});
const notice=document.createElement('aside');notice.className='shop-notice';notice.innerHTML='Test store · No live payments <a href="/cart/">Cart</a><a href="/my-account/">Account</a>';document.body.append(notice);
document.querySelectorAll('[class*=shopping-cart],[class*=cart-toggle]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();location.href='/cart/';},true));
const searchBtn=document.createElement('button');searchBtn.textContent='Search products';searchBtn.style.marginLeft='12px';notice.append(searchBtn);searchBtn.onclick=()=>{const d=document.createElement('dialog');d.className='shop-search';d.innerHTML='<button type="button">Close</button><label>Search products<input type="search" placeholder="Product name"></label><div class="results"></div>';document.body.append(d);$('button',d).onclick=()=>{d.close();d.remove();};$('input',d).oninput=async e=>{await catalogReady;$('.results',d).innerHTML=catalog.filter(p=>p.name.toLowerCase().includes(e.target.value.toLowerCase())).slice(0,15).map(p=>`<a href="${esc(p.path)}">${esc(p.name)} · ${money(p.price)}</a>`).join('');};d.showModal();$('input',d).focus();};
startPage().catch(e=>{const output=$('#shop-content');if(output)output.innerHTML=`<p role="alert" class="error">${esc(e.message)}</p><button onclick="location.reload()">Try again</button>`;});
});
async function renderCart(){const c=await api('/api/cart'),host=$('#shop-content');host.innerHTML=`<h1>Your cart</h1><p class="test-label">Test checkout only. No payment will be collected and no shipment will be made.</p>${c.items.length?c.items.map(i=>`<div class="row"><img src="${esc(i.image)}" alt=""><div class="info"><strong>${esc(i.name)}</strong><br>${money(i.price)}</div><label>Quantity<input type="number" min="0" max="99" data-id="${esc(i.id)}" value="${i.quantity}"></label><button data-remove="${esc(i.id)}">Remove</button><strong>${money(i.price*i.quantity)}</strong></div>`).join('')+`<h2>Subtotal ${money(c.total)}</h2><a class="button" href="/checkout/">Continue to test checkout</a>`:'<p>Your cart is empty.</p><a href="/shop-all-peptides/">Browse products</a>'}`;host.querySelectorAll('[data-id]').forEach(input=>input.onchange=async()=>{try{await api('/api/cart',{action:'set',id:input.dataset.id,quantity:Number(input.value)});await renderCart();}catch(e){toast(e.message);await renderCart();}});host.querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=async()=>{await api('/api/cart',{action:'set',id:btn.dataset.remove,quantity:0});await renderCart();});}
async function startPage(){const kind=document.body.dataset.shop;if(!kind)return;const host=$('#shop-content');if(kind==='cart')return renderCart();if(kind==='checkout'){const c=await api('/api/cart');if(!c.items.length){host.innerHTML='<h1>Your cart is empty</h1><a href="/shop-all-peptides/">Browse products</a>';return;}const key=crypto.randomUUID();host.innerHTML=`<h1>Test checkout</h1><p class="test-label">This creates a test order only. No payment, shipment, or inventory deduction occurs. Test shipping and tax are $0; live rates are not configured.</p><div class="columns"><form id="checkout-form">${['email','name','address','city','postal'].map(n=>`<label>${n==='postal'?'ZIP code':n[0].toUpperCase()+n.slice(1)}<input name="${n}" ${n==='email'?'type="email"':'type="text"'} required maxlength="200" autocomplete="${{email:'email',name:'name',address:'street-address',city:'address-level2',postal:'postal-code'}[n]}"></label>`).join('')}<label>Country<select name="country"><option value="US">United States</option></select></label><label><input type="checkbox" name="age" required> I am at least 21 years of age.</label><label><input type="checkbox" name="researcher" required> I am a qualified researcher purchasing for in vitro/laboratory research only.</label><button>Place test order</button><p id="checkout-error" role="alert" class="error"></p></form><section><h2>Order summary</h2>${c.items.map(i=>`<p>${esc(i.name)} × ${i.quantity} <strong>${money(i.price*i.quantity)}</strong></p>`).join('')}<h2>Test total ${money(c.total)}</h2></section></div>`;$('#checkout-form').onsubmit=async e=>{e.preventDefault();const f=e.target,btn=$('button',f),v=Object.fromEntries(new FormData(f));btn.disabled=true;$('#checkout-error').textContent='';try{const o=await api('/api/checkout',{key,email:v.email,shipping:{name:v.name,address:v.address,city:v.city,postal:v.postal,country:v.country},age:v.age==='on',researcher:v.researcher==='on'});host.innerHTML=`<h1>Test order saved</h1><p class="success">No payment was collected. No shipment will be made.</p><p>Order ${esc(o.id)}</p><p>Total ${money(o.total||c.total)}</p>${o.token?`<p><a href="/order-tracking/?id=${o.id}&token=${o.token}">View your test order</a></p><p>Save that private link to check this order again.</p>`:''}<a href="/shop-all-peptides/">Continue shopping</a>`;}catch(e){$('#checkout-error').textContent=e.message;}finally{btn.disabled=false;}};return;}
if(kind==='tracking'){const p=new URLSearchParams(location.search);host.innerHTML='<h1>Track an order</h1><p>Use the private tracking link saved after checkout, or sign in to view your orders.</p><a href="/my-account/">My account</a>';if(p.has('id')){const o=await api('/api/orders/'+encodeURIComponent(p.get('id'))+'?token='+encodeURIComponent(p.get('token')||''));host.innerHTML=`<h1>Order ${esc(o.id)}</h1><p class="test-label">Test order · ${esc(o.status)} · No shipment scheduled.</p>${o.items.map(i=>`<p>${esc(i.name)} × ${i.quantity}</p>`).join('')}<h2>${money(o.total)}</h2>`;}return;}
if(kind==='account'){const a=await api('/api/account');host.innerHTML=a.signedIn?`<h1>My account</h1><p>${esc(a.email)}</p><a href="/signout-with-chatgpt?return_to=%2Fmy-account%2F">Sign out</a>${a.admin?'<p><a href="/admin/">Store administration</a></p>':''}<h2>Your test orders</h2>${a.orders.length?a.orders.map(o=>`<p><a href="/order-tracking/?id=${o.id}">${esc(o.id)}</a> ${money(o.total)} · ${esc(o.status)}</p>`).join(''):'<p>No orders yet.</p>'}`:'<h1>My account</h1><p>Sign in to keep your test order history. Guest checkout is also available.</p><a class="button" href="/signin-with-chatgpt?return_to=%2Fmy-account%2F" target="_top">Sign in with ChatGPT</a>';return;}
if(kind==='admin'){const [ps,os,ss]=await Promise.all([api('/api/admin/products'),api('/api/admin/orders'),api('/api/admin/submissions')]);host.innerHTML=`<h1>Store administration</h1><p class="test-label">All orders are test orders. Inventory and prices below are independent of PH Bio Labs’ existing store.</p><h2>Test orders</h2>${os.orders.map(o=>`<details><summary>${esc(o.email)} · ${money(o.total)} · ${esc(o.status)}</summary><pre>${esc(JSON.stringify({items:JSON.parse(o.items),shipping:JSON.parse(o.shipping)},null,2))}</pre></details>`).join('')||'<p>No orders yet.</p>'}<h2>Customer requests</h2>${ss.submissions.map(s=>`<details><summary>${esc(s.kind)} · ${esc(s.created_at)}</summary><pre>${esc(s.data)}</pre></details>`).join('')||'<p>No requests yet.</p>'}<h2>Products</h2><p>Blank inventory means stock has not been supplied. Products with unconfigured variants cannot be purchased yet.</p><div class="scroll"><table><thead><tr><th>Product</th><th>Price USD</th><th>Stock</th><th>Active</th><th></th></tr></thead><tbody>${ps.products.map(p=>`<tr data-product="${esc(p.id)}"><td>${esc(p.name)}${p.variable?' · variants required':''}</td><td><input aria-label="Price for ${esc(p.name)}" name="price" type="number" step="0.01" min="0" value="${p.price/100}"></td><td><input aria-label="Stock for ${esc(p.name)}" name="stock" type="number" min="0" value="${p.stock??''}"></td><td><input aria-label="Active ${esc(p.name)}" name="active" type="checkbox" ${p.active?'checked':''}></td><td><button>Save</button></td></tr>`).join('')}</tbody></table></div>`;host.querySelectorAll('[data-product]').forEach(row=>$('button',row).onclick=async()=>{try{await api('/api/admin/products',{id:row.dataset.product,price:Math.round(Number($('[name=price]',row).value)*100),stock:$('[name=stock]',row).value===''?null:Number($('[name=stock]',row).value),active:$('[name=active]',row).checked?1:0});toast('Product saved.');}catch(e){toast(e.message);}});return;}
if(['contact','wholesale','white-label'].includes(kind)){host.innerHTML=`<h1>${kind==='contact'?'Contact PH Bio Labs':kind==='wholesale'?'Wholesale application':'White label inquiry'}</h1><form id="request-form"><label>Email<input type="email" name="email" required maxlength="254"></label><label>${kind==='contact'?'Message':'Tell us about your business and requirements'}<textarea name="message" required maxlength="5000" rows="7"></textarea></label><button>Submit request</button><p role="status" id="request-status"></p></form>`;$('#request-form').onsubmit=async e=>{e.preventDefault();const f=e.target,btn=$('button',f);btn.disabled=true;try{const v=Object.fromEntries(new FormData(f)),r=await api('/api/submissions',{kind,...v});$('#request-status').textContent=r.message;f.reset();}catch(e){$('#request-status').textContent=e.message;}finally{btn.disabled=false;}};}
}
